var powerlevel = global.get('heater.powerlevel');
var controlmode = global.get('heater.mode');
var targettemp = global.get('heater.targettemp');

// Prefix defines message sender 160=aa
const prefix = ['170','03'];
// Payload requires 2x HEX: FF which is Dec: 255
const payload = ['255','255'];

if (controlmode === "04") {
    // Add Mode value
   payload.push("04");
    // Add target Temp which is irelevant (dec 255 = Hex FF)
   payload.push("255");
    // Turn on Vent
   payload.push("01");

   // Convert Powerlevel to Hex
   var powerlevelhex = Number(powerlevel).toString(16);
   // add trailing 0 if to short..
   while (powerlevelhex.length < 2) {
        powerlevelhex = "0" + powerlevelhex;
    }
    // add value to array
   payload.push(powerlevelhex);

   var payloadlength = (payload.length).toString(16);
   while (payloadlength.length < 2) {
        payloadlength = "0" + payloadlength;
    }

    var finalcommand = prefix.concat(payloadlength,'00','01',payload);
    //msg.payload = finalcommand;
    msg.payload = Buffer.from(finalcommand, "hex");
  }

if ((controlmode === "21") || (controlmode === "22")) {
    // Add Mode value, as we have temperature, we need 02
   payload.push("02");
    // Add target Temp which is irelevant (dec 255 = Hex FF)
    // Convert target Temp  to Hex
    //var targettemphex = Number(targettemp).toString(16);
    // add trailing 0 if to short..
    //while (targettemphex.length < 2) {
    //     targettemphex = "0" + targettemphex;
    // }
     // add value to array
    payload.push(targettemp);

    // Turn on Vent
   payload.push("01");
   // Add powerlevel ahrdcoded this might be changed by the heater
   payload.push("03");

   var payloadlength = (payload.length).toString(16);
   while (payloadlength.length < 2) {
        payloadlength = "0" + payloadlength;
    }

    var finalcommand = prefix.concat(payloadlength,'00','01',payload);
    //msg.payload = finalcommand;
    msg.payload = Buffer.from(finalcommand, "hex");
  }

return msg;

